{"filePath":"/Users/dwahl/Scripts/pantoken/docs/scripts/canvas-rce-pwa.ts","content":"import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { Resvg } from "@resvg/resvg-js";

const APP_BASE = "/tools/canvas-rce/";
const BACKGROUND_COLOR = "#f5f5f5";
const THEME_COLOR = "#0d1b2a";
const ICON_SIZES = [192, 512] as const;

function replaceRequired(source: string, search: string, replacement: string): string {
  if (!source.includes(search)) {
    throw new Error(`Canvas RCE PWA metadata anchor not found: ${search}`);
  }
  return source.replace(search, replacement);
}

function appIconSvg(logoSvg: string): string {
  const mark = replaceRequired(
    logoSvg,
    "<svg ",
    '<svg x="32" y="32" width="64" height="64" ',
  );
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><rect width="128" height="128" fill="${BACKGROUND_COLOR}"/>${mark}</svg>`;
}

function writePng(svg: string, size: number, path: string): void {
  const png = new Resvg(svg, { fitTo: { mode: "width", value: size } }).render().asPng();
  writeFileSync(path, png);
}

/** Apply Pantoken install metadata and icons to the docs-only Canvas RCE render directory. */
export function configureCanvasRcePwa(renderDir: string, logoPath: string): void {
  const indexPath = join(renderDir, "index.html");
  let html = readFileSync(indexPath, "utf8");
  html = replaceRequired(
    html,
    '<meta name="application-name" content="Canvas Theme Editor" />',
    '<meta name="application-name" content="Pantoken" />',
  );
  html = replaceRequired(html, "<title>Canvas Theme Editor</title>", "<title>Pantoken</title>");
  html = replaceRequired(
    html,
    '<link rel="manifest" href="/manifest.webmanifest" />',
    `<link rel="manifest" href="/manifest.webmanifest" />
    <link rel="icon" href="/icon-192.png" sizes="192x192" type="image/png" data-pantoken-themed-icon />
    <link rel="apple-touch-icon" href="/apple-touch-icon.png" sizes="180x180" />`,
  );
  writeFileSync(indexPath, html);

  const publicDir = join(renderDir, "public");
  const manifestPath = join(publicDir, "manifest.webmanifest");
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8")) as Record<string, unknown>;
  Object.assign(manifest, {
    id: APP_BASE,
    name: "Pantoken",
    short_name: "Pantoken",
    start_url: APP_BASE,
    scope: APP_BASE,
    background_color: BACKGROUND_COLOR,
    theme_color: THEME_COLOR,
    icons: ICON_SIZES.map((size) => ({
      src: `${APP_BASE}icon-${size}.png`,
      sizes: `${size}x${size}`,
      type: "image/png",
      purpose: "any maskable",
    })),
  });
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);

  const iconSvg = appIconSvg(readFileSync(logoPath, "utf8"));
  for (const size of ICON_SIZES) {
    writePng(iconSvg, size, join(publicDir, `icon-${size}.png`));
  }
  writePng(iconSvg, 180, join(publicDir, "apple-touch-icon.png"));
}
"}

{"filePath":"/Users/dwahl/Scripts/pantoken/docs/scripts/canvas-rce-pwa.test.ts","content":"import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, test } from "vite-plus/test";
import { configureCanvasRcePwa } from "./canvas-rce-pwa.ts";

const logoPath = join(
  import.meta.dirname,
  "..",
  "..",
  "plugins",
  "pantoken",
  "logos",
  "assets",
  "logos",
  "pantoken",
  "icon-color.svg",
);

function pngDimensions(png: Buffer): [number, number] {
  expect(png.subarray(1, 4).toString("ascii")).toBe("PNG");
  return [png.readUInt32BE(16), png.readUInt32BE(20)];
}

test("brands the docs Canvas RCE as an installable Pantoken app", () => {
  const renderDir = mkdtempSync(join(tmpdir(), "pantoken-canvas-rce-pwa-"));
  const publicDir = join(renderDir, "public");
  mkdirSync(publicDir);
  writeFileSync(
    join(renderDir, "index.html"),
    `<!doctype html><head>
    <meta name="application-name" content="Canvas Theme Editor" />
    <link rel="manifest" href="/manifest.webmanifest" />
    <title>Canvas Theme Editor</title>
    </head>`,
  );
  writeFileSync(
    join(publicDir, "manifest.webmanifest"),
    JSON.stringify({ description: "Preserved", display: "standalone", icons: [] }),
  );

  configureCanvasRcePwa(renderDir, logoPath);

  const html = readFileSync(join(renderDir, "index.html"), "utf8");
  expect(html).toContain('<meta name="application-name" content="Pantoken" />');
  expect(html).toContain("<title>Pantoken</title>");
  expect(html).toContain('href="/icon-192.png"');
  expect(html).toContain("data-pantoken-themed-icon");
  expect(html).toContain('href="/apple-touch-icon.png"');

  const manifest = JSON.parse(readFileSync(join(publicDir, "manifest.webmanifest"), "utf8"));
  expect(manifest).toMatchObject({
    id: "/tools/canvas-rce/",
    name: "Pantoken",
    short_name: "Pantoken",
    start_url: "/tools/canvas-rce/",
    scope: "/tools/canvas-rce/",
    description: "Preserved",
    display: "standalone",
    background_color: "#f5f5f5",
    theme_color: "#0d1b2a",
  });
  expect(manifest.icons).toEqual([
    {
      src: "/tools/canvas-rce/icon-192.png",
      sizes: "192x192",
      type: "image/png",
      purpose: "any maskable",
    },
    {
      src: "/tools/canvas-rce/icon-512.png",
      sizes: "512x512",
      type: "image/png",
      purpose: "any maskable",
    },
  ]);
  expect(pngDimensions(readFileSync(join(publicDir, "icon-192.png")))).toEqual([192, 192]);
  expect(pngDimensions(readFileSync(join(publicDir, "icon-512.png")))).toEqual([512, 512]);
  expect(pngDimensions(readFileSync(join(publicDir, "apple-touch-icon.png")))).toEqual([180, 180]);
});

test("fails when scaffold metadata anchors drift", () => {
  const renderDir = mkdtempSync(join(tmpdir(), "pantoken-canvas-rce-pwa-drift-"));
  mkdirSync(join(renderDir, "public"));
  writeFileSync(join(renderDir, "index.html"), "<title>Unexpected</title>");

  expect(() => configureCanvasRcePwa(renderDir, logoPath)).toThrow(
    "Canvas RCE PWA metadata anchor not found",
  );
});
"}

